-- Reference design only. Implementation migrations must add immutable-field triggers.
PRAGMA foreign_keys = ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE workflows(id TEXT PRIMARY KEY, next_version INTEGER NOT NULL DEFAULT 1 CHECK(next_version>0), next_audit_seq INTEGER NOT NULL DEFAULT 1 CHECK(next_audit_seq>0), created_at INTEGER NOT NULL);
CREATE TABLE drafts(id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), name TEXT NOT NULL, document_json TEXT NOT NULL CHECK(json_valid(document_json)), revision INTEGER NOT NULL CHECK(revision>0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE definition_versions(id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), version INTEGER NOT NULL CHECK(version>0), canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json)), digest TEXT NOT NULL CHECK(length(digest)=64), registry_digest TEXT NOT NULL CHECK(length(registry_digest)=64), published_at INTEGER NOT NULL, UNIQUE(workflow_id,version));
CREATE TABLE definition_events(workflow_id TEXT NOT NULL REFERENCES workflows(id), seq INTEGER NOT NULL CHECK(seq>0), event_type TEXT NOT NULL, actor TEXT NOT NULL, entity_id TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(CAST(payload_json AS BLOB))<=16384), created_at INTEGER NOT NULL, PRIMARY KEY(workflow_id,seq));
CREATE TABLE runs(id TEXT PRIMARY KEY, definition_version_id TEXT NOT NULL REFERENCES definition_versions(id), input_json TEXT NOT NULL CHECK(json_valid(input_json)), input_digest TEXT NOT NULL CHECK(length(input_digest)=64), start_actor TEXT NOT NULL, start_key TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('QUEUED','ACTIVE','FAILING','CANCELLING','SUCCEEDED','FAILED','CANCELLED')), paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN (0,1)), deadline_at INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), next_event_seq INTEGER NOT NULL DEFAULT 1 CHECK(next_event_seq>0), created_at INTEGER NOT NULL, started_at INTEGER, finished_at INTEGER, failure_code TEXT, UNIQUE(start_actor,start_key));
CREATE TABLE tasks(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), node_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('worker','timer','approval')), handler TEXT, handler_version INTEGER, state TEXT NOT NULL CHECK(state IN ('BLOCKED','READY','RUNNING','RETRY_WAIT','WAITING_TIMER','WAITING_APPROVAL','SUCCEEDED','FAILED','SKIPPED','CANCELLED')), input_json TEXT CHECK(input_json IS NULL OR json_valid(input_json)), input_digest TEXT, output_json TEXT CHECK(output_json IS NULL OR json_valid(output_json)), ready_at INTEGER, next_eligible_at INTEGER, timer_due_at INTEGER, fence INTEGER NOT NULL DEFAULT 0 CHECK(fence>=0), claim_count INTEGER NOT NULL DEFAULT 0 CHECK(claim_count>=0), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), reason_code TEXT, UNIQUE(run_id,node_id), UNIQUE(id,run_id), UNIQUE(id,run_id,node_id), CHECK((kind='worker' AND handler IS NOT NULL AND handler_version>0) OR (kind<>'worker' AND handler IS NULL AND handler_version IS NULL)));
CREATE TABLE dependencies(run_id TEXT NOT NULL, task_id TEXT NOT NULL, parent_task_id TEXT NOT NULL, PRIMARY KEY(task_id,parent_task_id), CHECK(task_id<>parent_task_id), FOREIGN KEY(task_id,run_id) REFERENCES tasks(id,run_id), FOREIGN KEY(parent_task_id,run_id) REFERENCES tasks(id,run_id));
CREATE TABLE workers(id TEXT PRIMARY KEY, capacity INTEGER NOT NULL CHECK(capacity>0), capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)), state TEXT NOT NULL CHECK(state IN ('ACTIVE','DRAINING','STOPPED')), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), registered_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL);
CREATE TABLE attempts(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), worker_id TEXT NOT NULL REFERENCES workers(id), attempt_no INTEGER NOT NULL CHECK(attempt_no>0), fence INTEGER NOT NULL CHECK(fence>0), state TEXT NOT NULL CHECK(state IN ('RUNNING','SUCCEEDED','FAILED','TIMED_OUT','LOST','CANCELLED')), lease_expires_at INTEGER NOT NULL, execution_deadline_at INTEGER NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER, error_code TEXT, error_message TEXT, UNIQUE(task_id,attempt_no), UNIQUE(task_id,fence), UNIQUE(id,task_id), CHECK(lease_expires_at<=execution_deadline_at));
CREATE UNIQUE INDEX one_running_attempt ON attempts(task_id) WHERE state='RUNNING';
CREATE TABLE fixtures(id TEXT PRIMARY KEY, generator_version TEXT NOT NULL, seed INTEGER NOT NULL, manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)), created_at INTEGER NOT NULL);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, run_id TEXT, task_id TEXT, fixture_id TEXT REFERENCES fixtures(id), content_type TEXT NOT NULL, payload BLOB NOT NULL CHECK(length(payload)<=8388608), digest TEXT NOT NULL CHECK(length(digest)=64), created_at INTEGER NOT NULL, FOREIGN KEY(task_id,run_id) REFERENCES tasks(id,run_id), CHECK((run_id IS NOT NULL AND task_id IS NOT NULL AND fixture_id IS NULL) OR (run_id IS NULL AND task_id IS NULL AND fixture_id IS NOT NULL)));
CREATE TABLE approval_requests(id TEXT PRIMARY KEY, task_id TEXT NOT NULL UNIQUE, run_id TEXT NOT NULL, definition_version_id TEXT NOT NULL REFERENCES definition_versions(id), input_json TEXT NOT NULL CHECK(json_valid(input_json)), input_digest TEXT NOT NULL CHECK(length(input_digest)=64), revision INTEGER NOT NULL CHECK(revision>0), reviewer_role TEXT NOT NULL, deadline_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED')), created_at INTEGER NOT NULL, FOREIGN KEY(task_id,run_id) REFERENCES tasks(id,run_id));
CREATE TABLE approval_decisions(id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE REFERENCES approval_requests(id), decision TEXT NOT NULL CHECK(decision IN ('APPROVE','REJECT')), actor TEXT NOT NULL, reason TEXT NOT NULL, input_digest TEXT NOT NULL CHECK(length(input_digest)=64), decision_key TEXT NOT NULL, decided_at INTEGER NOT NULL);
CREATE TABLE effects(run_id TEXT NOT NULL, node_id TEXT NOT NULL, operation TEXT NOT NULL, task_id TEXT NOT NULL, attempt_id TEXT NOT NULL, payload_digest TEXT NOT NULL CHECK(length(payload_digest)=64), artifact_id TEXT NOT NULL REFERENCES artifacts(id), created_at INTEGER NOT NULL, PRIMARY KEY(run_id,node_id,operation), FOREIGN KEY(task_id,run_id,node_id) REFERENCES tasks(id,run_id,node_id), FOREIGN KEY(attempt_id,task_id) REFERENCES attempts(id,task_id));
CREATE TABLE history_events(run_id TEXT NOT NULL REFERENCES runs(id), seq INTEGER NOT NULL CHECK(seq>0), event_type TEXT NOT NULL, actor TEXT NOT NULL, entity_id TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(CAST(payload_json AS BLOB))<=16384), created_at INTEGER NOT NULL, PRIMARY KEY(run_id,seq));
CREATE TABLE idempotency_receipts(actor TEXT NOT NULL, operation TEXT NOT NULL, target TEXT NOT NULL, request_key TEXT NOT NULL, request_digest TEXT NOT NULL CHECK(length(request_digest)=64), response_status INTEGER NOT NULL, response_json TEXT NOT NULL CHECK(json_valid(response_json)), run_id TEXT REFERENCES runs(id), created_at INTEGER NOT NULL, PRIMARY KEY(actor,operation,target,request_key));
CREATE INDEX ready_tasks ON tasks(state,ready_at,id) WHERE state='READY';
CREATE INDEX retry_due ON tasks(next_eligible_at,id) WHERE state='RETRY_WAIT';
CREATE INDEX timer_due ON tasks(timer_due_at,id) WHERE state='WAITING_TIMER';
CREATE INDEX lease_expiry ON attempts(lease_expires_at,id) WHERE state='RUNNING';
CREATE INDEX attempt_deadline ON attempts(execution_deadline_at,id) WHERE state='RUNNING';
CREATE INDEX attempt_capacity ON attempts(state,worker_id,task_id);
CREATE INDEX task_capacity ON tasks(run_id,handler,handler_version,id);
CREATE INDEX dependency_parent ON dependencies(parent_task_id,task_id);
CREATE INDEX run_list ON runs(phase,created_at DESC,id DESC);
CREATE INDEX run_deadline ON runs(deadline_at,id) WHERE phase IN ('QUEUED','ACTIVE');
CREATE INDEX approval_inbox ON approval_requests(state,reviewer_role,deadline_at,id);
CREATE INDEX artifacts_by_task ON artifacts(task_id,id);
